import Database from 'better-sqlite3';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Data generated by visitors on the running site (currently just page views).
// Deliberately NOT in the catalog database: that file is a deploy artifact
// regenerated from the pipeline and committed, so mixing live traffic into it
// would mean local test traffic shipping to production and production traffic
// being overwritten on every deploy. This file is never committed.
//
// Locally it lives in backend/data/live/. On Railway the container filesystem
// is wiped on every redeploy, so point PT_LIVE_DB_PATH at a path on an attached
// persistent volume (e.g. /data/live.sqlite) -- without that, counts reset on
// each deploy.
export const LIVE_DB_PATH =
  process.env.PT_LIVE_DB_PATH || path.join(__dirname, '..', '..', 'data', 'live', 'live.sqlite');

fs.mkdirSync(path.dirname(LIVE_DB_PATH), { recursive: true });

const liveDb = new Database(LIVE_DB_PATH);
liveDb.pragma('journal_mode = WAL');
liveDb.exec(`
CREATE TABLE IF NOT EXISTS page_views (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,        -- 'view' (a site section) | 'book' (a book detail panel)
  view TEXT,                 -- section name when kind = 'view'
  book_id INTEGER,           -- when kind = 'book' (no FK: different database file)
  session_id TEXT NOT NULL,  -- random per-browser-session id; not tied to a person
  viewed_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_page_views_viewed_at ON page_views(viewed_at);
CREATE INDEX IF NOT EXISTS idx_page_views_book_id ON page_views(book_id);
`);

export default liveDb;
